(()=>{
  const ns='http://www.w3.org/2000/svg';
  const style=document.createElement('style');style.textContent=`
  .side-inspect{width:min(720px,94vw);max-height:94vh;border:1px solid #a7b8be;border-radius:14px;padding:24px;color:#20302d;background:#fff}.side-inspect::backdrop{background:#101b24a8}.side-inspect header{display:flex;justify-content:space-between;align-items:center;gap:16px}.side-inspect h2{font:600 20px system-ui;margin:0}.side-inspect button{font:14px system-ui;padding:9px 14px;border:1px solid #9bafb5;border-radius:6px;background:#f5f8f8;cursor:pointer}.side-inspect .side-stage{width:min(512px,100%);margin:20px auto}.side-inspect p{font:14px/1.5 system-ui}.side-component-controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.side-canvas{color:#000;display:block;width:100%;height:auto;background:#fff}.side-bound{opacity:0;pointer-events:none;fill:none;stroke-width:.3;stroke-dasharray:1 .6}.side-canvas:hover .side-bound,.side-canvas:focus .side-bound{opacity:1}.side-canvas[data-active="main"] .side-bound-main,.side-canvas[data-active="sub"] .side-bound-sub{opacity:1;stroke-width:.55}.side-bound-main{stroke:#bd4b30}.side-bound-sub{stroke:#146dc5}.pair-result-card img[role=button]{cursor:zoom-in}.side-thumb{display:inline-block;position:relative;line-height:0;cursor:zoom-in}.side-thumb svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.side-thumb:hover .side-bound,.side-thumb:focus-within .side-bound{opacity:1}`;document.head.append(style);
  const dialog=document.createElement('dialog');dialog.className='side-inspect';dialog.innerHTML='<header><h2></h2><button type="button" aria-label="Close preview">Close</button></header><div class="side-stage"></div><div class="side-component-controls"><button data-role="main">Main bounds</button><button data-role="sub">Sub bounds</button><a download>Download SVG</a></div><p>64×64 canvas · one-unit grid · heavier lines every 8 units. Hover the main or sub icon to inspect its painted bounds. Orange: main; blue: sub.</p><p class="side-dimensions"></p>';document.body.append(dialog);dialog.querySelector('header button').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}};
  function element(name,attrs){const e=document.createElementNS(ns,name);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);return e;}
  function bounds(svg,result){for(const p of result.placements){const b=p.painted_box;svg.append(element('rect',{x:b.x,y:b.y,width:b.w,height:b.h,class:'side-bound side-bound-'+p.role}));}}
  function addSubCenterline(svg){
    const group=svg.querySelector('[id="state-icon"]');if(!group)return;
    const trace=group.cloneNode(true);trace.setAttribute('data-sub-centerline','true');trace.setAttribute('pointer-events','none');trace.setAttribute('aria-hidden','true');
    // Canvas-relative line width, preserving the original curves and placement transform.
    const scale=Math.abs(Number((group.getAttribute('transform')||'').match(/scale\(([-+.\deE]+)/)?.[1]||1));
    for(const e of [trace,...trace.querySelectorAll('*')]){e.removeAttribute('id');e.setAttribute('stroke','#ef4444');e.setAttribute('stroke-width',String(.45/scale));e.setAttribute('fill','none');e.removeAttribute('vector-effect');}
    svg.append(trace);
  }
  function open(name,result){
    const svg=new DOMParser().parseFromString(result.svg,'image/svg+xml').documentElement;svg.setAttribute('class','side-canvas');svg.setAttribute('viewBox','0 0 64 64');svg.removeAttribute('width');svg.removeAttribute('height');svg.setAttribute('role','img');svg.setAttribute('aria-label',name+' on a 64 by 64 grid');
    const grid=element('g',{'aria-hidden':'true','pointer-events':'none'});for(let i=0;i<=64;i++){const a={stroke:i%8===0?'#9eb3bd':'#dae4e9','stroke-width':i%8===0?.13:.055};grid.append(element('line',{x1:i,y1:0,x2:i,y2:64,...a}),element('line',{x1:0,y1:i,x2:64,y2:i,...a}));}svg.prepend(grid);addSubCenterline(svg);bounds(svg,result);
    for(const [role,id]of [['main','main-icon-clipped'],['sub','state-icon']]){const g=svg.querySelector('[id="'+id+'"]');if(g){g.addEventListener('pointerenter',()=>svg.dataset.active=role);g.addEventListener('pointerleave',()=>delete svg.dataset.active);}}
    dialog.querySelector('h2').textContent=name;dialog.querySelector('.side-stage').replaceChildren(svg);dialog.querySelector('.side-dimensions').textContent=result.placements.map(p=>`${p.role}: ${p.painted_box.w.toFixed(2)} × ${p.painted_box.h.toFixed(2)} at (${p.painted_box.x.toFixed(2)}, ${p.painted_box.y.toFixed(2)})`).join(' · ');
    for(const b of dialog.querySelectorAll('[data-role]')){b.onmouseenter=b.onfocus=()=>svg.dataset.active=b.dataset.role;b.onmouseleave=b.onblur=()=>delete svg.dataset.active;b.onclick=()=>svg.dataset.active=b.dataset.role;}
    const a=dialog.querySelector('a');a.href='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(result.svg);a.download=result.filename||'combination.svg';window.SideRepairFlags?.popup(dialog,result);dialog.showModal();
  }
  function attach(image,name,result){image.setAttribute('role','button');image.tabIndex=0;image.setAttribute('aria-label','Inspect '+name);const launch=async()=>{try{if(!result.svg){const response=await fetch(result.url);if(!response.ok)throw Error('Preview could not be loaded');result.svg=await response.text();}open(name,result);}catch(e){image.title=e.message;}};image.onclick=launch;image.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();launch();}};const wrap=document.createElement('span');wrap.className='side-thumb';image.replaceWith(wrap);wrap.append(image);const overlay=element('svg',{viewBox:'0 0 64 64','aria-hidden':'true'});bounds(overlay,result);wrap.append(overlay);}
  window.SideCombinationPopup={open,attach,addSubCenterline};
})();
